const chatHaste = -1001;
const popupHaste = -1002;
export const boatHaste = 5;

// haste:-4 interval:1100
// haste:-3 interval:600
// haste:-2 interval:433
// haste:-1 interval:350 (world)
// haste:0 interval:300 (scout, mage, knight)
// haste:1 interval:266 (hunter or others with haste)
// haste:2 interval:242
// haste:3 interval:225
// haste:4 interval:211
// haste:5 interval:200
// haste:6 interval:190
// haste:7 interval:183
export const getHasteInterval = (world: World, haste: number) =>
  haste === chatHaste
    ? 10
    : haste === popupHaste
    ? 175
    : Math.floor(1000 / (Math.max(haste, -4) + 5) + 100);

export const getTempo = (world: World, position: Position) =>
  sum(
    getCellEntities(world, position).map((target) => target[TEMPO]?.amount || 0)
  );

export const getEntityHaste = (world: World, entity: Entity) =>
  isInTab(world, entity, "chat")
    ? chatHaste
    : isInPopup(world, entity)
    ? popupHaste
    : isMounting(world, entity)
    ? boatHaste
    : getEntityStats(world, entity).haste;

export const getCollidable = (world: World, position: Position) =>
  getCellEntities(world, position).find(
    (entity) => COLLIDABLE in (entity as Entity)
  );

export const isCollision = (world: World, position: Position) =>
  !!getCollidable(world, position);

export const isPassable = (
  world: World,
  position: Position,
  exclude?: Entity
) => {
  if (
    !getOverlappingCell(
      world.metadata.gameEntity[LEVEL].initialized,
      position.x,
      position.y
    )
  )
    return false;

  const lockable = getLockable(world, position);
  const collidable = getCollidable(world, position);
  const attackable = getAttackable(world, position);

  return (
    (!collidable || collidable === exclude) &&
    (!attackable || attackable === exclude) &&
    !(lockable && isLocked(world, lockable)) &&
    !getLootable(world, position) &&
    !getCollecting(world, position) &&
    !getClickable(world, position)
  );
};

export const isFloatable = (
  world: World,
  position: Position,
  exclude?: Entity
) => isPassable(world, position, exclude) && isImmersible(world, position);

export const isWalkable = (
  world: World,
  position: Position,
  exclude?: Entity
) => isPassable(world, position, exclude) && !isSubmerged(world, position);

export const isRoamable = (
  world: World,
  entity: Entity,
  position: Position
) => {
  // avoid fires
  const castableEntity = getExertables(world, position).map((exertable) =>
    world.getEntityByIdAndComponents(exertable[EXERTABLE].castable, [CASTABLE])
  )[0];
  const isFire = castableEntity && castableEntity[CASTABLE].burn > 0;
  if (isFire) return false;

  // don't walk through open locks
  const isLockable = getLockable(world, position);
  if (isLockable) return false;

  if (!isMovable(world, entity, position)) return false;

  return true;
};

export const isLimbWalkable = (
  world: World,
  entity: Entity,
  position: Position
) => {
  if (entity[FRAGMENT]?.structure) {
    const fragmentEntity = getFragment(world, position);

    if (
      fragmentEntity &&
      entity[FRAGMENT].structure === fragmentEntity[FRAGMENT]?.structure
    )
      return true;
  }

  return isWalkable(world, position);
};

export const isFlyable = (world: World, position: Position) => {
  const lockable = getLockable(world, position);
  return (
    !getOpaque(world, position) && !(lockable && isLocked(world, lockable))
  );
};

export const isMovable = (world: World, entity: Entity, position: Position) => {
  if (!entity[MOVABLE]) return false;

  if (isLimbWalkable(world, entity, position)) return true;

  const spikable = getSpikable(world, position);
  if (spikable && isNeutral(world, spikable)) return false;

  // allow attacking opposing entities
  const attackable = getAttackable(world, position);
  if (
    entity[EQUIPPABLE]?.weapon &&
    attackable &&
    !isFriendlyFire(world, entity, attackable)
  )
    return true;

  // allow clicking
  const clickable = getClickable(world, position);
  if (clickable && (!clickable[CLICKABLE].player || entity[PLAYER]))
    return true;

  return false;
};

export const getBiome = (world: World, position: Position): BiomeName => {
  const biomes = world.metadata.gameEntity[LEVEL].biomes;
  if (biomes.length === 0) return "jungle";

  return getOverlappingCell(
    world.metadata.gameEntity[LEVEL].biomes,
    position.x,
    position.y
  );
};

export default function setupMovement(world: World) {
  let referenceGenerations = -1;
  const entityReferences: Record<string, number> = {};
  const nextSail: Record<string, number> = {};

  const onUpdate = (delta: number) => {
    const size = world.metadata.gameEntity[LEVEL].size;
    const hero = world.getEntity([PLAYER, POSITION, LAYER]);

    const generation = world
      .getEntities([RENDERABLE, REFERENCE])
      .reduce((total, entity) => entity[RENDERABLE].generation + total, 0);

    if (referenceGenerations === generation) return;

    referenceGenerations = generation;

    // let displacable units and mobs take precendence over player movements
    const orderedEntities = [
      ...(world.getEntities([
        POSITION,
        MOVABLE,
        RENDERABLE,
        `!${PLAYER}` as unknown as typeof PLAYER,
      ]) as TypedEntity<"POSITION" | "MOVABLE" | "RENDERABLE">[]),
      ...world.getEntities([POSITION, MOVABLE, RENDERABLE, PLAYER]),
    ];

    for (const entity of orderedEntities) {
      const entityId = world.getEntityId(entity);
      const movableReference = world.assertByIdAndComponents(
        entity[MOVABLE].reference,
        [REFERENCE, RENDERABLE]
      );
      const entityReference = movableReference[RENDERABLE].generation;

      // skip if reference frame is unchanged
      if (entityReferences[entityId] === entityReference) continue;

      entityReferences[entityId] = entityReference;

      const pushSound = entity[DISPLACABLE]?.pushSound;
      delete entity[DISPLACABLE]?.pushSound;
      const pendingOrientation = entity[MOVABLE].pendingOrientation;
      entity[MOVABLE].pendingOrientation = undefined;

      // skip if immovable or not sliding
      if (
        isDead(world, entity) ||
        (FRAGMENT in entity && isDead(world, getRoot(world, entity))) ||
        (isFrozen(world, entity) && !entity[MOVABLE].momentum)
      )
        continue;

      const attemptedOrientations: Orientation[] = [
        ...entity[MOVABLE].orientations,
      ];

      if (
        pendingOrientation &&
        !attemptedOrientations.includes(pendingOrientation)
      ) {
        attemptedOrientations.push(pendingOrientation);
      }

      if (entity[MOVABLE].momentum) {
        attemptedOrientations.unshift(entity[MOVABLE].momentum);
      }

      // skip if no attempted movement
      if (attemptedOrientations.length === 0) continue;

      // set facing regardless of movement
      const rigid = entity[STRUCTURABLE]?.rigid;
      if (entity[ORIENTABLE] && !entity[MOVABLE].flying && !rigid)
        entity[ORIENTABLE].facing = attemptedOrientations[0];

      // skip if already interacted
      if (
        entity[MOVABLE].lastInteraction === entityReference &&
        !entity[MOVABLE].momentum
      )
        continue;

      // move whole rigid body
      const limbs = rigid ? getLimbs(world, entity) : [entity];
      let movedOrientation: Orientation | undefined;

      for (const orientation of attemptedOrientations) {
        const delta = orientationPoints[orientation];
        let obstructed = false;

        for (const limb of limbs) {
          const position = combine(size, limb[POSITION], delta);
          if (
            (!limb[MOVABLE].swimming &&
              isLimbWalkable(world, limb, position)) ||
            (limb[MOVABLE].flying && isFlyable(world, position)) ||
            (limb[MOVABLE].swimming &&
              isFloatable(world, position) &&
              isImmersible(world, limb[POSITION]))
          ) {
            continue;
          }
          obstructed = true;
          break;
        }

        if (!obstructed) {
          movedOrientation = orientation;
          break;
        }
      }

      if (movedOrientation) {
        if (pushSound) play("push");
        const delta = orientationPoints[movedOrientation];
        const rootPosition = combine(size, entity[POSITION], delta);
        // play sound
        const proximity =
          getCellEntities(world, rootPosition).filter(
            (cell) => cell[RENDERABLE] && cell[SPRITE]?.layers.length
          ).length > 0
            ? 1
            : 0.5;

        const boat = entity[MOUNTABLE]?.medium === "water";
        if (boat && isImmersible(world, entity[POSITION])) {
          const distance = hero
            ? getDistance(hero[POSITION], entity[POSITION], size)
            : Infinity;
          if (distance < 10 && entityReference >= (nextSail[entityId] ?? 0)) {
            play("sail", { proximity: 1 / (distance + 1) });
            nextSail[entityId] = entityReference + 5;
          }
        }

        if (entity[PLAYER]) {
          const variant = isImmersible(world, rootPosition)
            ? 3
            : getTempo(world, rootPosition) < 0
            ? 2
            : 1;
          play("move", {
            intensity: movableReference[REFERENCE].tick,
            variant,
            proximity,
          });
        } else if (entity[NPC] && entity[FOG]?.visibility === "visible") {
          play("slide", {
            intensity: movableReference[REFERENCE].tick,
            proximity: hero
              ? 1 / (getDistance(hero[POSITION], entity[POSITION], size) + 1)
              : 0.5,
            variant: npcVariants[entity[NPC].type],
            delay: random(0, 50),
          });
        }

        const passenger = world.getEntityByIdAndComponents(
          entity[MOUNTABLE]?.passenger,
          [MOVABLE]
        );
        const parts = [...limbs, ...(passenger ? [passenger] : [])];

        for (const part of parts) {
          // leave bubble trail if walking through water
          if (isImmersible(world, part[POSITION]) && !part[MOVABLE].flying) {
            createBubble(world, part[POSITION], "water", !boat);
          }

          // set facing to actual movement
          if (!rigid && part[ORIENTABLE] && !part[MOVABLE].flying) {
            part[ORIENTABLE].facing = movedOrientation;
          }

          const limbPosition = combine(size, part[POSITION], delta);
          moveEntity(world, part, limbPosition);
          rerenderEntity(world, part);
        }
      } else {
        if (
          entity[MOVABLE].swimming &&
          !isImmersible(world, entity[POSITION])
        ) {
          // bump stranded entities
          if (!(BUMPABLE in entity)) {
            world.addComponentToEntity(entity, BUMPABLE, {
              generation: 0,
            });
          }

          if (entity[BUMPABLE]) {
            entity[BUMPABLE].generation = entity[RENDERABLE].generation;
            entity[BUMPABLE].orientation = "up";
            rerenderEntity(world, entity);
          }
        }
        if (entity[MOUNTABLE]) {
          // reset movement for vessels
          stopVessel(world, entity);
        }
      }

      // preserve momentum before suspending frame
      freezeMomentum(world, entity, movedOrientation);

      // mark as interacted but keep pending movement
      entity[MOVABLE].lastInteraction = entityReference;
    }
  };

  return { onUpdate };
}
